from mk import *
STRICT["on"] = True
import math
t1 = (25 - math.sqrt(625 - 120)) / 2

def fig():
    g = Fig(560, 330, "תרשים א: רמזור בראשית ציר x ושוטר על אופנוע ב-x=30 מטר. תרשים ב: מהירות המכונית 25 מטר לשנייה עד 5 שניות ואחר כך יורדת לאפס ב-15 שניות; מהירות האופנוע עולה מאפס ל-30 ב-15 שניות")
    g.ground(40, 520, 90, depth=8)
    g.rect(78, 20, 10, 70, fill="var(--d-label)", stroke="none", width=0)
    for y in (26, 42, 58):
        g.circle(83, y, 5, fill="var(--d-fill)")
    g.line(83, 98, 520, 98, width=1.5); g.text(83, 116, "0", cls="dim"); g.text(183, 116, "30", cls="dim"); g.line(183, 94, 183, 102, width=1.5)
    g.text(520, 116, "x (m)", cls="dim", anchor="end")
    g.motorcycle(183, 90, 46)
    g.arrow(330, 50, 440, 50, None); g.heb(385, 42, "כיוון התנועה")
    g.heb(300, 130, "תרשים א")
    X, Y = g.graph(80, 300, 380, 140, "t (s)", "v (m/s)", xticks=[(5, "5"), (15, "15")], yticks=[(25, "25"), (30, "30")], xmax=16, ymax=30, grid=False)
    g.plot(X, Y, [(0, 25), (5, 25), (15, 0)])
    g.plot(X, Y, [(0, 0), (15, 30)], stroke="var(--d-line)")
    g.line(X(5), Y(25), X(5), Y(0), stroke="var(--d-dim)", width=1, dash="4 3")
    g.guide(X, Y, 15, 30)
    g.heb(X(2.5), Y(25) - 8, "מכונית"); g.heb(X(11.5), Y(23) - 6, "אופנוע")
    return g

E(id="bagrut-2008-q1", year=2008, label="2008 שאלה 1", topic="kinematics", sub="kin-straight-line", diff=3, fig=fig,
  stem=r"בתרשים א מוצגים רמזור בצומת, וציר מקום $x$ שראשיתו ברמזור. הציר נמשך לאורך כביש ישר, וכיוונו החיובי ימינה. בנקודה $x = 30$ מטר על הכביש הזה מחכה שוטר על אופנוע לנהגים שעוברים בכיוון התנועה. נהג מכונית לא שם לב שהרמזור אדום, וחוצה את הצומת ברגע $t = 0$. השוטר רואה את המכונית ומתחיל לנסוע בכיוון התנועה באותו רגע. בתרשים ב מוצגות המהירויות של המכונית ושל האופנוע כפונקציה של הזמן.",
  parts=[
    P("א", r"הראו שהתאוצה של האופנוע היא $2\,\text{m/s}^2$, והסבירו מה המשמעות הפיזיקלית של המשפט \"התאוצה של האופנוע היא $2\,\text{m/s}^2$\".", num(2, "m/s^2"), ["graph", "understanding"], [
        X(r"הכיוון החיובי נקבע בשאלה: ימינה, כיוון התנועה. התאוצה היא השיפוע של גרף המהירות."),
        S(r"השיפוע של הגרף של האופנוע", r"קו ישר מאפס עד שלושים מטר לשנייה, בחמש-עשרה שניות", r"a_m = \frac{30 - 0}{15 - 0} = 2\,\text{m/s}^2", eq=r"\bar a = \frac{\Delta v}{\Delta t}"),
        S(r"המשמעות", r"בכל שנייה המהירות של האופנוע גדלה בשני מטר לשנייה", r"a = \frac{2\,\text{m/s}}{1\,\text{s}}"),
    ], r"$2\,\text{m/s}^2$: בכל שנייה מהירות האופנוע גדלה ב-$2\,\text{m/s}$", key=r"2 m/s^2"),
    P("ב", r"מה התאוצה של המכונית, לפי ציר $x$, בפרק הזמן $t = 5\,\text{s}$ עד $t = 15\,\text{s}$? מה המשמעות הפיזיקלית של התאוצה שקיבלתם?", num(-2.5, "m/s^2"), ["graph", "signs"], [
        S(r"השיפוע של הגרף של המכונית בקטע השני", r"המהירות יורדת מעשרים וחמש לאפס בעשר שניות", r"a_c = \frac{0 - 25}{15 - 5} = -2.5\,\text{m/s}^2", eq=r"\bar a = \frac{\Delta v}{\Delta t}"),
        S(r"המשמעות", r"הסימן השלילי אומר שהתאוצה נגד כיוון התנועה, ולכן המכונית מאטה. בכל שנייה המהירות שלה קטנה בשניים וחצי מטר לשנייה", r"v > 0,\quad a < 0"),
    ], r"$-2.5\,\text{m/s}^2$: בכל שנייה מהירות המכונית קטנה ב-$2.5\,\text{m/s}$", key=r"a=−2.5 m/s^2"),
    P("ג", r"מי מקדים את מי ברגע $t = 15\,\text{s}$? נמקו.", choice(["המכונית", "האופנוע"], 1), ["graph", "algebra"], [
        X(r"המקום בכל רגע הוא המקום ההתחלתי ועוד השטח שמתחת לגרף המהירות."),
        S(r"המקום של המכונית", r"המכונית יוצאת מהרמזור, כלומר מהראשית. השטח שמתחת לגרף שלה הוא מלבן ועוד משולש", r"x_c = 0 + 25 \cdot 5 + \tfrac{1}{2} \cdot 10 \cdot 25 = 125 + 125 = 250\,\text{m}"),
        S(r"המקום של האופנוע", r"האופנוע יוצא משלושים מטר. השטח שמתחת לגרף שלו הוא משולש", r"x_m = 30 + \tfrac{1}{2} \cdot 15 \cdot 30 = 30 + 225 = 255\,\text{m}"),
    ], r"האופנוע: $255\,\text{m}$, לעומת $250\,\text{m}$ של המכונית", key=r"האופנוע מקדים את המכונית"),
    P("ד", r"כמה פעמים חלפו כלי הרכב זה על פני זה בפרק הזמן $t = 0$ עד $t = 15\,\text{s}$? הסבירו.", num(2, ""), ["graph", "algebra"], [
        S(r"בהתחלה", r"האופנוע לפני המכונית, אבל המכונית מהירה ממנו", r"x_c(0) = 0 < x_m(0) = 30\,\text{m}"),
        S(r"המקומות בחמש השניות הראשונות", r"המכונית נוסעת במהירות קבועה, והאופנוע יוצא ממנוחה בתאוצה קבועה", r"x_c = 25t \qquad x_m = 30 + 0 \cdot t + \tfrac{1}{2} \cdot 2 \cdot t^2 = 30 + t^2", eq=r"x = x_0 + v_0 t + \tfrac{1}{2}at^2"),
        S(r"החלפה ראשונה: המכונית עוקפת", r"משווים את המקומות ומסדרים למשוואה ריבועית. הפתרון הקטן הוא העקיפה הראשונה", r"t^2 - 25t + 30 = 0 \;\Rightarrow\; t = \frac{25 - \sqrt{505}}{2} \approx 1.26\,\text{s}"),
        S(r"החלפה שנייה: האופנוע עוקף", r"אחרי חמש-עשרה שניות האופנוע שוב לפני המכונית, לפי סעיף ג. לכן הוא עקף אותה בדרך", r"x_m(15) = 255\,\text{m} > x_c(15) = 250\,\text{m}"),
    ], r"$2$ פעמים: המכונית עוקפת אחרי $\approx 1.26\,\text{s}$, והאופנוע עוקף לפני $15\,\text{s}$"),
    P("ה", r"האם בפרק הזמן $t = 0$ עד $t = 15\,\text{s}$ המהירות הממוצעת של האופנוע גדולה מהמהירות הממוצעת של המכונית, קטנה ממנה או שווה לה? נמקו.", choice(["גדולה", "קטנה", "שווה"], 1), ["algebra"], [
        S(r"המהירות הממוצעת של המכונית", r"ההעתק חלקי הזמן", r"\bar v_c = \frac{250 - 0}{15} \approx 16.7\,\text{m/s}", eq=r"\bar v = \frac{\Delta x}{\Delta t}"),
        S(r"המהירות הממוצעת של האופנוע", r"ההעתק שלו קטן יותר, כי הוא התחיל שלושים מטר קדימה", r"\bar v_m = \frac{255 - 30}{15} = 15\,\text{m/s}"),
    ], r"קטנה: $15$ לעומת $16.7\,\text{m/s}$. האופנוע מקדים רק בזכות שלושים המטרים שהיו לו בהתחלה", key=r"המהירות הממוצעת של המכונית גדולה יותר"),
    P("ו", r"מתי המהירות של האופנוע שווה למהירות של המכונית?", num(37.5 / 4.5, "s"), ["graph", "algebra"], [
        X(r"הגרפים נחתכים בקטע השני של המכונית, שבו היא מאטה."),
        S(r"משוואות המהירות בקטע הזה", r"האופנוע יוצא ממנוחה. המכונית מתחילה את הקטע אחרי חמש שניות, במהירות עשרים וחמש", r"v_m = 0 + 2t \qquad v_c = 25 + (-2.5)(t - 5)", eq=r"v = v_0 + at"),
        S(r"משווים", r"פותחים סוגריים ומעבירים את האיברים עם הזמן לאגף אחד", r"2t = 37.5 - 2.5t \;\Rightarrow\; 4.5t = 37.5"),
        S(r"מחלקים", r"משוואה ממעלה ראשונה", r"t = \frac{37.5}{4.5} \approx 8.33\,\text{s}"),
    ], r"$\approx 8.33\,\text{s}$", key=r"8.33 s"),
  ],
  concepts=["גרף מהירות-זמן", "משמעות התאוצה", "תאוצה שלילית", "עקיפה", "מהירות ממוצעת"],
  summary=r"מכונית שעוברת ברמזור אדום ושוטר על אופנוע: תאוצות מגרפים, מי מקדים, כמה עקיפות, ומהירות ממוצעת.",
  note=r"נקודת חיתוך של גרפי מהירות היא רגע של מהירויות שוות, לא של מפגש.")
